// Reads the message WhatsApp sent us and keeps only what we need.
// WhatsApp also sends "delivered" / "read" updates - those are ignored.
// You should not need to edit this node.

const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const value = change.value || {};
      const contact = (value.contacts || [])[0] || {};
      for (const msg of value.messages || []) {
        let text = "";
        let choiceId = "";
        if (msg.type === "text") text = msg.text.body;
        if (msg.type === "button") text = msg.button.text;
        if (msg.type === "interactive") {
          const reply = msg.interactive.list_reply || msg.interactive.button_reply || {};
          choiceId = reply.id || "";
          text = reply.title || "";
        }
        out.push({
          json: {
            phoneNumberId: (value.metadata || {}).phone_number_id,
            from: msg.from,
            name: (contact.profile || {}).name || "",
            messageId: msg.id,
            messageType: msg.type,
            text: (text || "").trim(),
            choiceId,
          },
        });
      }
    }
  }
}
return out;

// =====================================================================
//  WHATSAPP AUTO-REPLY  -  edit YOUR AGENCY and the REPLIES below.
//  No JavaScript knowledge needed. Keep the "double quotes" and the
//  commas at the end of each line. Use \n for a new line.
//  WhatsApp formatting: *bold*  _italic_
//  Everything marked FILL_IN is a placeholder - replace it.
// =====================================================================

// ---------------------------------------------------------------------
//  YOUR AGENCY
// ---------------------------------------------------------------------
const AGENCY = {
  name: "FILL_IN Agency Name",
  website: "https://FILL_IN-your-website.com",
  hours: "Mon-Sat, 10am-7pm IST",
  // Notion database for people who ask to talk to a person.
  // Leave "" to switch this off. (Can be the same database as lead scoring.)
  notionLeadsDatabaseId: "",
};

// ---------------------------------------------------------------------
//  MENU  -  the options people can tap. Max 10 options.
//  id     = internal name (lowercase, no spaces) - must match a REPLY below
//  title  = what they see (max 24 characters)
//  detail = small grey text under the title (max 72 characters)
// ---------------------------------------------------------------------
const MENU = [
  { id: "services",  title: "Our services",       detail: "What we do for brands" },
  { id: "pricing",   title: "Pricing",            detail: "Packages and starting prices" },
  { id: "work",      title: "Our work",           detail: "Case studies and portfolio" },
  { id: "website",   title: "Website & pages",    detail: "Links to our site and socials" },
  { id: "book",      title: "Book a call",        detail: "Pick a time that suits you" },
  { id: "human",     title: "Talk to a person",   detail: "A team member will reply" },
];

// ---------------------------------------------------------------------
//  REPLIES  -  what the bot says for each menu option.
//  words = if someone TYPES any of these, they get this reply
//          (lowercase; matches whole words in their message).
//  ORDER MATTERS: if a message matches several topics, the one HIGHER
//  in this list wins. "hi, how much for SEO?" -> pricing, not services.
// ---------------------------------------------------------------------
const REPLIES = {

  pricing: {
    words: ["price", "prices", "pricing", "cost", "rate", "charges", "package", "packages", "budget", "how much", "fees"],
    text:
      "*Pricing*\n\n" +
      "• FILL_IN Starter - from ₹FILL_IN/month\n" +
      "• FILL_IN Growth - from ₹FILL_IN/month\n" +
      "• Custom projects - quoted after a free call\n\n" +
      "Full details: " + AGENCY.website + "/pricing",
  },

  book: {
    words: ["book", "call", "meeting", "appointment", "demo", "consultation", "schedule"],
    text:
      "*Book a free call* 📅\n\n" +
      "Pick a time here: https://FILL_IN-booking-link\n\n" +
      "Our hours: " + AGENCY.hours,
  },

  human: {
    words: ["human", "person", "someone", "agent", "talk to", "speak to", "call me", "urgent"],
    wantsHuman: true,
    text:
      "Thanks {{name}}! 🙌 A member of our team will reply here soon.\n\n" +
      "Our hours: " + AGENCY.hours + ".\n" +
      "Tell us a little about your business and what you need, and we'll come prepared.",
  },

  work: {
    words: ["portfolio", "work", "case study", "case studies", "clients", "results", "examples"],
    text:
      "*Our work*\n\n" +
      "Case studies: " + AGENCY.website + "/work\n" +
      "Instagram: https://instagram.com/FILL_IN\n" +
      "Behance: https://behance.net/FILL_IN",
  },

  website: {
    words: ["website", "site", "link", "instagram", "linkedin", "facebook", "pages", "socials"],
    text:
      "*Find us online*\n\n" +
      "🌐 Website: " + AGENCY.website + "\n" +
      "📸 Instagram: https://instagram.com/FILL_IN\n" +
      "💼 LinkedIn: https://linkedin.com/company/FILL_IN\n" +
      "📘 Facebook: https://facebook.com/FILL_IN",
  },

  services: {
    words: ["service", "services", "what do you do", "offer", "seo", "ads", "social", "website design"],
    text:
      "*Our services*\n\n" +
      "• *FILL_IN Service 1* - one line about it\n" +
      "• *FILL_IN Service 2* - one line about it\n" +
      "• *FILL_IN Service 3* - one line about it\n" +
      "• *FILL_IN Service 4* - one line about it\n\n" +
      "Details: " + AGENCY.website + "/services",
  },

  welcome: {
    words: ["hi", "hello", "hey", "hii", "namaste", "menu", "start", "options"],
    text:
      "Hi {{name}}! 👋 Welcome to *" + AGENCY.name + "*.\n\n" +
      "We help brands grow with FILL_IN one-line pitch.\n\n" +
      "Tap *See options* below to explore, or just type what you need.",
  },

  notUnderstood: {
    text:
      "Sorry, I didn't catch that. 🙏\n\n" +
      "Tap *See options* below, or type *person* to talk to our team.",
  },

  notText: {
    wantsHuman: true,
    text:
      "Thanks for sending that! I can only read text messages, so a team member " +
      "will take a look and reply here.\n\nOur hours: " + AGENCY.hours,
  },

};

// Label on the button that opens the menu (max 20 characters).
const MENU_BUTTON = "See options";

// =====================================================================
//  ENGINE - you should not need to edit below this line.
// =====================================================================

function pickTopic(msg) {
  if (msg.choiceId && REPLIES[msg.choiceId]) return msg.choiceId;
  if (!msg.text) return msg.messageType === "text" ? "welcome" : "notText";
  const t = " " + msg.text.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, " ") + " ";
  // Topics are checked top to bottom, so the order of REPLIES matters.
  for (const key of Object.keys(REPLIES)) {
    const words = REPLIES[key].words || [];
    if (words.some((w) => t.includes(" " + w.toLowerCase() + " ") || (w.includes(" ") && t.includes(w.toLowerCase())))) {
      return key;
    }
  }
  return "notUnderstood";
}

function buildBody(to, text) {
  if (text.length <= 1024) {
    return {
      messaging_product: "whatsapp",
      recipient_type: "individual",
      to,
      type: "interactive",
      interactive: {
        type: "list",
        body: { text },
        footer: { text: AGENCY.name.slice(0, 60) },
        action: {
          button: MENU_BUTTON.slice(0, 20),
          sections: [{
            title: "Menu",
            rows: MENU.slice(0, 10).map((m) => ({
              id: m.id, title: m.title.slice(0, 24), description: (m.detail || "").slice(0, 72),
            })),
          }],
        },
      },
    };
  }
  // Too long for a menu message - send as plain text instead.
  return {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to,
    type: "text",
    text: { preview_url: true, body: text.slice(0, 4096) },
  };
}

return $input.all().map((item) => {
  const msg = item.json;
  const topic = pickTopic(msg);
  const reply = REPLIES[topic];
  const firstName = (msg.name || "").split(" ")[0];
  const text = reply.text.replace(/\{\{name\}\}/g, firstName || "there");
  return {
    json: {
      ...msg,
      topic,
      wantsHuman: Boolean(reply.wantsHuman),
      notionLeadsDatabaseId: AGENCY.notionLeadsDatabaseId,
      saveLead: Boolean(reply.wantsHuman) && AGENCY.notionLeadsDatabaseId.trim() !== "",
      replyText: text,
      whatsappBody: buildBody(msg.from, text),
    },
  };
});

